package com.agacostays.billing.controller;
import com.agacostays.billing.dto.request.*;import com.agacostays.billing.dto.response.*;import com.agacostays.billing.service.BillingService;import jakarta.validation.Valid;import org.springframework.data.domain.Pageable;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/billing") public class BillingController{private final BillingService s;public BillingController(BillingService x){s=x;}@PostMapping("/bookings/{bookingId}/generate")public ResponseEntity<ApiResponse<FinalBillResponse>> gen(@PathVariable Long bookingId,@Valid @RequestBody GenerateFinalBillRequest r){return ResponseEntity.ok(ApiResponse.ok("Final bill generated",s.generate(bookingId,r.branchId(),r.customerId())));}@GetMapping("/bookings/{bookingId}")public ResponseEntity<ApiResponse<FinalBillResponse>> byBooking(@PathVariable Long bookingId){return ResponseEntity.ok(ApiResponse.ok("Bill fetched",s.getByBooking(bookingId)));}@GetMapping("/my-bill/{bookingId}")public ResponseEntity<ApiResponse<FinalBillResponse>> my(@PathVariable Long bookingId){return ResponseEntity.ok(ApiResponse.ok("Bill fetched",s.getByBooking(bookingId)));}@GetMapping("/{billId}")public ResponseEntity<ApiResponse<FinalBillResponse>> byId(@PathVariable Long billId){return ResponseEntity.ok(ApiResponse.ok("Bill fetched",s.getById(billId)));}@PostMapping("/{billId}/discount")public ResponseEntity<ApiResponse<FinalBillResponse>> discount(@PathVariable Long billId,@Valid @RequestBody ApplyDiscountRequest r){return ResponseEntity.ok(ApiResponse.ok("Discount applied",s.applyDiscount(billId,r)));}@PostMapping("/{billId}/pay")public ResponseEntity<ApiResponse<PaymentStatusResponse>> pay(@PathVariable Long billId,@Valid @RequestBody PayFinalBillRequest r){return ResponseEntity.ok(ApiResponse.ok("Payment initiated",s.pay(billId,r)));}@PostMapping("/final-bill/{bookingId}/pay")public ResponseEntity<ApiResponse<PaymentStatusResponse>> payBooking(@PathVariable Long bookingId,@Valid @RequestBody PayFinalBillRequest r){return ResponseEntity.ok(ApiResponse.ok("Payment initiated",s.pay(s.getByBooking(bookingId).billId(),r)));}@GetMapping("/{billId}/charges")public ResponseEntity<ApiResponse<List<BillChargeResponse>>> charges(@PathVariable Long billId){return ResponseEntity.ok(ApiResponse.ok("Charges fetched",s.charges(billId)));}}
